n = int(input())
cs = {}
for i in range(n):
  a, c = map(int, input().split())
  if c in cs:
    cs[c].append(a)
  else:
    cs[c] = [a]

max_min_deliciousness = 0
for k in cs.keys():
  m = min(cs[k])
  if m > max_min_deliciousness:
    max_min_deliciousness = m
print(max_min_deliciousness)
